#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const catalog=JSON.parse(fs.readFileSync(path.join(root,'packages/agentsam-errors/protocol/error-catalog.json'),'utf8'));
const check=process.argv.includes('--check');
const sanitize=(text)=>String(text??'').replaceAll('|','\\|');
const reasons=catalog.reasons.slice().sort((a,b)=>a.name.localeCompare(b.name));
const lines=[
 '# Canonical AgentSam Error Reasons',
 '',
 'Generated by scripts/registry/generate-error-docs.mjs from packages/agentsam-errors/protocol/error-catalog.json. Do not edit manually.',
 '',
 '| Reason | Code | Domain | Remediation | Owner | Retryable |',
 '| --- | --- | --- | --- | --- | --- |',
 ...reasons.map(r=>'| '+[r.name,r.code,r.domain,r.remediation_action,r.resolution_owner,String(r.retryable)].map(sanitize).join(' | ')+' |'),
 '',
];
const readme=[
 '# @inneranimalmedia/agentsam-errors',
 '',
 'Canonical AgentSam error classification and remediation contracts.',
 '',
 'This package currently defines '+catalog.codes.length+' canonical codes, '+catalog.reasons.length+
 ' reason records, '+catalog.domains.length+' domains, and '+catalog.remediation_actions.length+' remediation actions.',
 '',
 'CLI commands should create typed failures through usageError / processError and render them through renderCliError.',
 'Usage errors exit with 2; execution failures exit with 1. --json preserves the canonical envelope.',
 'HTTP status lines are intentionally omitted from local human CLI failures.',
 '',
 'Reason mappings are generated in docs/reference/AGENTSAM-ERROR-REASONS.md.',
 '',
 'Operator-facing next-step guidance remains incremental: new helpers ship first with machine and',
 'the remaining legacy command error sites are tracked in scripts/registry/plain-error-baseline.json.',
 '',
].join('\n');
const files=[
 ['packages/agentsam-errors/README.md',readme],
 ['docs/reference/AGENTSAM-ERROR-REASONS.md',lines.join('\n')]
];
const drift=files.filter(([name,data])=>{
 const dest=path.join(root,name);
 return !fs.existsSync(dest)||fs.readFileSync(dest,'utf8')!==data;
}).map(([name])=>name);
if(check){
 if(drift.length){console.error('Error docs drift: '+drift.join(', '));process.exitCode=1;}
 else console.log('Generated error docs PASS · '+reasons.length+' reasons');
}else{
 for(const [name,data]of files)fs.writeFileSync(path.join(root,name),data);
 console.log('Generated error docs · '+reasons.length+' reasons');
}
